// Pure checks of the Phase-7 view models (assets/hq-carnet-reviews.js) on the REAL JSON the server returns
// (tests/fixtures_carnet_reviews.json, generated by tests/gen_fixtures_carnet_reviews.py from the Python implementation).
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { createRequire } from "node:module";

const require = createRequire(import.meta.url);
const R = require("../assets/hq-carnet-reviews.js");
const FX = JSON.parse(readFileSync(new URL("./fixtures_carnet_reviews.json", import.meta.url), "utf8"));
let groups = 0;
const group = (name, fn) => {
  try {
    fn();
    groups += 1;
  } catch (e) {
    console.error("FAIL group:", name);
    throw e;
  }
};
const clone = (x) => JSON.parse(JSON.stringify(x));
const PR = "proj-" + "b".repeat(8);
const SN = "snap-" + "c".repeat(24);
const REQ = "a".repeat(32);

group("text validation", () => {
  assert.equal(R.validTitle("  Revue  ").text, "Revue");
  assert.equal(R.validTitle("").ok, false);
  assert.equal(R.validTitle("x".repeat(121)).ok, false);
  assert.equal(R.validTitle("a\u0000b").ok, false);
  assert.equal(R.validNote("a\nb").ok, true);
  assert.equal(R.validNote("a\u0001b").ok, false);
  assert.equal(R.validCheck("x".repeat(501)).ok, false);
  assert.equal(R.validQuestion("Q\n?").ok, true);
  assert.equal(R.hex32(new Uint8Array(16).fill(255)), "f".repeat(32));
  assert.equal(R.hex32(new Uint8Array(3)), null);
});

group("create attempt: one request id per unchanged form, new id when the form changes", () => {
  let n = 0;
  const mint = () => (++n).toString(16).padStart(32, "0");
  const a = R.createAttempt(null, PR, " T ", "n", null, mint);
  assert.equal(a.rid, "0".repeat(31) + "1");
  assert.equal(R.createAttempt(a, PR, "T", "n", null, mint).rid, a.rid); // normalized-equal form = same attempt (uncertain retry)
  assert.equal(R.createAttempt(a, PR, "T2", "n", null, mint).rid, "0".repeat(31) + "2"); // changed title = new attempt
  assert.notEqual(R.createAttempt(a, PR, "T", "n2", null, mint).rid, a.rid);
  assert.notEqual(R.createAttempt(a, PR, "T", "n", SN, mint).rid, a.rid);
  assert.notEqual(R.createAttempt(a, "proj-" + "d".repeat(8), "T", "n", null, mint).rid, a.rid);
  assert.equal(R.createAttempt({ sig: a.sig, rid: "bad" }, PR, "T", "n", null, mint).rid.length, 32); // a malformed pending id is never reused
});

group("wire bodies: exact shapes, identity only, expected_rev everywhere", () => {
  assert.deepEqual(R.createBody(PR, " T ", "n", REQ, null), { action: "review_create", project_id: PR, title: "T", note: "n", request_id: REQ });
  assert.deepEqual(R.createBody(PR, "T", "", REQ, SN).baseline, { kind: "snapshot", snapshot_id: SN });
  assert.equal(R.createBody("nope", "T", "", REQ), null);
  assert.equal(R.createBody(PR, "", "", REQ), null);
  assert.equal(R.createBody(PR, "T", "", "short"), null);
  const pack = FX.pack.review;
  const u = R.updateBody(pack, { status: "reviewed" });
  assert.deepEqual(u, { action: "review_update", id: pack.id, expected_rev: pack.rev, status: "reviewed" });
  assert.equal(R.updateBody(pack, { status: "approved" }), null);
  assert.equal(R.updateBody(pack, {}), null);
  assert.equal(R.itemAddBody(pack, { kind: "project_overview" }).expected_rev, pack.rev);
  assert.equal(R.itemRemoveBody(pack, "bad"), null);
  assert.equal(R.checkAddBody(pack, "x", ["ri-" + "0".repeat(16)]).refs.length, 0); // refs to unknown items are dropped, never sent
  assert.deepEqual(R.checkAddBody(pack, "x", [pack.items[0].id]).refs, [pack.items[0].id]);
  assert.equal(R.checkUpdateBody(pack, pack.checklist[0].id, { checked: "yes" }), null);
  assert.equal(R.checkUpdateBody(pack, pack.checklist[0].id, { checked: false }).checked, false);
  assert.equal(R.questionUpdateBody(pack, pack.questions[0].id, { state: "done" }), null);
  assert.equal(R.questionUpdateBody(pack, pack.questions[0].id, { state: "resolved", resolution_note: "ok" }).state, "resolved");
});

group("delete needs the revision the confirmation was opened on", () => {
  const pack = FX.pack.review;
  const b = R.deleteBody(pack, pack.rev - 1);
  assert.equal(b.expected_rev, pack.rev - 1);
  assert.equal(b.confirm, true);
  assert.equal(R.deleteBody(pack, null), null);
});

group("evidence specs are strict identity-only shapes", () => {
  assert.deepEqual(R.pageSpec("page-abcd1234", "T").spec, { kind: "page", page_id: "page-abcd1234" });
  assert.equal(R.pageSpec("../x"), null);
  assert.deepEqual(R.blockSpec("decision", "page-abcd1234", "block-abcd1234", "D").spec, { kind: "decision", page_id: "page-abcd1234", block_id: "block-abcd1234" });
  assert.equal(R.blockSpec("page", "page-abcd1234", "block-abcd1234"), null);
  assert.equal(R.drawingSpec("plan-1").spec.stem, "plan-1");
  assert.equal(R.drawingSpec("../plan"), null);
  assert.equal(R.snapshotSpec("snap-zz"), null);
  assert.deepEqual(R.overviewSpec().spec, { kind: "project_overview" });
  assert.deepEqual(R.diffSpec(SN, null, null, null, "c").spec, { kind: "diff", base: SN, to: null, page_id: null, project_id: null });
  assert.equal(R.diffSpec("bad base!", null, null, null), null);
});

group("ask spec: only evidence/partial, scope exact, fingerprint as shown", () => {
  const ok = { status: "evidence", fingerprint: "f".repeat(32), question: "palier H7" };
  const it = R.askSpec(ok, { kind: "project", id: PR });
  assert.deepEqual(it.spec, { kind: "ask_result", question: "palier H7", scope: { kind: "project", id: PR }, limit: 10, fingerprint: "f".repeat(32) });
  assert.equal(R.askSpec({ ...ok, status: "insufficient" }, { kind: "notebook" }), null);
  assert.equal(R.askSpec({ ...ok, fingerprint: "zz" }, { kind: "notebook" }), null);
  assert.equal(R.askSpec(ok, { kind: "weird" }), null);
  assert.deepEqual(R.askSpec(ok, { kind: "notebook" }).spec.scope, { kind: "notebook" });
});

group("list model on the real server list", () => {
  const m = R.listModel(FX.list);
  assert.equal(m.rows.length, 1);
  assert.equal(m.rows[0].statusLabel, "Brouillon");
  assert.equal(m.rows[0].readOnly, false);
  assert.match(m.rows[0].counts, /8 preuves/);
  const bad = clone(FX.list);
  bad.reviews[0].integrity = "corrupt";
  const b = R.listModel(bad).rows[0];
  assert.equal(b.readOnly, true);
  assert.match(b.integrityLabel, /lecture seule/);
});

group("pack model: stored copy and observation stay structurally separate", () => {
  const m = R.packModel(FX.pack.review, FX.freshness.freshness, "ok");
  assert.equal(m.items.length, 8);
  const page = m.items.find((i) => i.kind === "page");
  assert.equal(page.observation.state, "changed");
  assert.equal(page.observation.label, "Modifié depuis la sélection");
  assert.ok(page.copy.some((l) => l.includes("H7")), "the stored copy still says H7");
  assert.equal(page.copyNote, R.COPY_NOTE);
  assert.ok(!("state" in page.copy) && Array.isArray(page.copy));
  assert.equal(m.items.find((i) => i.kind === "decision").observation.state, "unchanged");
  assert.deepEqual(m.freshnessCounts.map((c) => c.n), [4, 4, 0, 0]);
  const ask = m.items.find((i) => i.kind === "ask_result");
  assert.equal(ask.replaceable, true);
  assert.equal(ask.question, "palier H7");
  const diff = m.items.find((i) => i.kind === "diff");
  assert.ok(diff.copy.length > 0);
});

group("without an observation every item says so, never 'unchanged'", () => {
  const m = R.packModel(FX.pack.review, null, "ok");
  assert.ok(m.items.every((i) => i.observation.state === "unknown" && i.observation.label === "Non observé"));
  assert.equal(m.freshnessCounts, null);
});

group("checklist and questions: manual state only; dangling refs stay visible", () => {
  const pack = clone(FX.pack.review);
  const m0 = R.packModel(pack, FX.freshness.freshness, "ok");
  assert.equal(m0.checklist[0].checked, true);
  assert.equal(m0.checkedCount, 1);
  assert.equal(m0.questions[0].state, "open");
  assert.equal(m0.questions[0].stateLabel, "Ouverte");
  const gone = pack.items[0].id;
  pack.items = pack.items.slice(1); // the evidence was removed: user-authored state is untouched
  const m1 = R.packModel(pack, null, "ok");
  assert.equal(m1.checklist[0].checked, true);
  assert.equal(m1.checklist[0].refs[0].dangling, true);
  assert.equal(m1.checklist[0].refs[0].id, gone);
  pack.questions[0].state = "resolved";
  assert.equal(R.packModel(pack, null, "ok").questions[0].stateLabel, "Marquée résolue par toi");
});

group("snapshot-bound observation says frozen / current differs in words", () => {
  const o = R.observationModel({ state: "unchanged", frozen: "ok", current_differs: true }, { kind: "snapshot", id: SN, seal: "a".repeat(64) });
  assert.match(o.frozen, /figé/);
  assert.match(o.currentDiffers, /diffère/);
  const u = R.observationModel({ state: "unknown", frozen: "unavailable", current_differs: null, reason: "frozen_snapshot_corrupt" }, { kind: "snapshot", id: SN });
  assert.match(u.frozen, /indisponible/);
  assert.match(u.reason, /altéré/);
  const live = R.observationModel({ state: "unchanged" }, { kind: "live" });
  assert.equal(live.frozen, "");
  const dr = R.observationModel({ state: "changed", anomaly: "drawing_bytes_changed" }, { kind: "live" });
  assert.match(dr.anomaly, /immuable/);
});

group("read-only (corrupt) pack", () => {
  const m = R.packModel(FX.pack.review, null, "corrupt");
  assert.equal(m.readOnly, true);
  assert.match(m.integrityLabel, /lecture seule/);
});

group("conflicts: reload the server version, retry nothing", () => {
  const c = R.conflictInfo({ data: FX.conflict });
  assert.deepEqual([c.code, c.conflict, c.reload, c.evidenceChanged], ["review_conflict", true, true, false]);
  assert.equal(R.conflictInfo({ data: { code: "review_evidence_changed", error: "x" } }).evidenceChanged, true);
  assert.equal(R.conflictInfo({ data: { code: "review_baseline_locked", error: "x" } }).reload, false);
  assert.equal(R.conflictInfo(new Error("net")).message, "net");
});

group("vocabulary: no evaluative or approval words are produced by the models", () => {
  const m = R.packModel(FX.pack.review, FX.freshness.freshness, "ok");
  const allowed = new Set([...Object.values(R.STATUS_LABEL), ...Object.values(R.STATE_LABEL)]);
  assert.ok(allowed.has(m.statusLabel));
  const blob = JSON.stringify([R.STATUS_LABEL, R.STATE_LABEL, R.KIND_LABEL, R.REASON_LABEL, R.ANOMALY_LABEL, m.freshnessCounts, R.NOT_VERDICT, R.COPY_NOTE]);
  for (const w of ["amélior", "dégrad", "plus sûr", "approuv", "conforme", "validé", "risque", "recommand", "régress", "résolu automatiquement"]) assert.ok(!blob.toLowerCase().includes(w), w);
});

group("source: no HTML injection, no dynamic evaluation in the review UI", () => {
  for (const f of ["../assets/hq-carnet-reviews.js", "../assets/hq-carnet-reviews-ui.js"]) {
    const src = readFileSync(new URL(f, import.meta.url), "utf8");
    for (const bad of ["innerHTML", "outerHTML", "insertAdjacentHTML", "document.write", "eval(", "new Function", "localStorage", "sessionStorage"]) assert.ok(!src.includes(bad), f + ": " + bad);
  }
});

console.log("check_hq_carnet_reviews: " + groups + " groups OK");
